export type PaneDirection = "horizontal" | "vertical";

export type PaneLeafNode = { type: "leaf"; leafId: string };

export type PaneSplitNode = {
  type: "split";
  direction: PaneDirection;
  first: PaneNode;
  second: PaneNode;
  ratio: number;
};

export type PaneNode = PaneLeafNode | PaneSplitNode;

export const MIN_PANE_RATIO = 0.1;
export const MAX_PANE_RATIO = 0.9;

/** Clamps a ratio into the usable range, falling back to an even split for non-finite input. */
export function clampRatio(ratio: number): number {
  if (!Number.isFinite(ratio)) return 0.5;
  return Math.min(MAX_PANE_RATIO, Math.max(MIN_PANE_RATIO, ratio));
}

export function createLeafNode(leafId?: string): PaneNode {
  return { type: "leaf", leafId: leafId ?? createLeafId() };
}

/**
 * Replaces the leaf `targetLeafId` with a split containing that leaf and a new leaf.
 * `position` decides which side the new leaf takes. Returns the original tree when
 * the target leaf does not exist.
 */
export function splitLeaf(
  root: PaneNode,
  targetLeafId: string,
  newLeafId: string,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): PaneNode {
  return mapLeaf(root, targetLeafId, (leaf) => {
    const newLeaf = createLeafNode(newLeafId);
    return {
      type: "split",
      direction,
      first: position === "first" ? newLeaf : leaf,
      second: position === "first" ? leaf : newLeaf,
      ratio: clampRatio(ratio),
    };
  });
}

/**
 * Removes the leaf `targetLeafId`, collapsing its parent split into the surviving sibling.
 * Returns `null` when the removed leaf was the whole tree, and the original tree when the
 * leaf does not exist.
 */
export function removeLeaf(root: PaneNode, targetLeafId: string): PaneNode | null {
  if (root.type === "leaf") return root.leafId === targetLeafId ? null : root;

  const first = removeLeaf(root.first, targetLeafId);
  if (first === null) return root.second;
  if (first !== root.first) return { ...root, first };

  const second = removeLeaf(root.second, targetLeafId);
  if (second === null) return root.first;
  if (second !== root.second) return { ...root, second };

  return root;
}

/**
 * Sets the ratio of the split addressed by a dot-notation `path` such as "" (root),
 * "first", or "second.first". Returns the original tree when the path does not resolve
 * to a split node.
 */
export function setRatioAtPath(root: PaneNode, path: string, ratio: number): PaneNode {
  const segments = path.split(".").filter((segment) => segment.length > 0);
  return applyRatio(root, segments, clampRatio(ratio));
}

export function findFirstLeafId(root: PaneNode): string {
  let node = root;
  while (node.type === "split") node = node.first;
  return node.leafId;
}

export function collectLeafIds(root: PaneNode): string[] {
  const ids: string[] = [];
  const visit = (node: PaneNode) => {
    if (node.type === "leaf") {
      ids.push(node.leafId);
      return;
    }
    visit(node.first);
    visit(node.second);
  };
  visit(root);
  return ids;
}

/**
 * Returns the first leaf id inside the sibling subtree of `targetLeafId`,
 * or `null` when the leaf is missing or is the tree root.
 */
export function findSiblingLeafId(root: PaneNode, targetLeafId: string): string | null {
  if (root.type === "leaf") return null;

  const inFirst = containsLeaf(root.first, targetLeafId);
  const inSecond = containsLeaf(root.second, targetLeafId);

  if (inFirst) {
    return root.first.type === "leaf"
      ? findFirstLeafId(root.second)
      : findSiblingLeafId(root.first, targetLeafId);
  }
  if (inSecond) {
    return root.second.type === "leaf"
      ? findFirstLeafId(root.first)
      : findSiblingLeafId(root.second, targetLeafId);
  }
  return null;
}

/**
 * Swaps the positions of two leaves. Returns the original tree when either leaf is
 * missing or when both ids refer to the same leaf.
 */
export function swapLeaves(root: PaneNode, sourceLeafId: string, targetLeafId: string): PaneNode {
  if (sourceLeafId === targetLeafId) return root;
  if (!containsLeaf(root, sourceLeafId) || !containsLeaf(root, targetLeafId)) return root;

  const swap = (node: PaneNode): PaneNode => {
    if (node.type === "leaf") {
      if (node.leafId === sourceLeafId) return { type: "leaf", leafId: targetLeafId };
      if (node.leafId === targetLeafId) return { type: "leaf", leafId: sourceLeafId };
      return node;
    }
    const first = swap(node.first);
    const second = swap(node.second);
    if (first === node.first && second === node.second) return node;
    return { ...node, first, second };
  };

  return swap(root);
}

/** Resets every split in the tree to an even 0.5 ratio. */
export function equalizeRatios(root: PaneNode): PaneNode {
  if (root.type === "leaf") return root;
  const first = equalizeRatios(root.first);
  const second = equalizeRatios(root.second);
  if (first === root.first && second === root.second && root.ratio === 0.5) return root;
  return { ...root, first, second, ratio: 0.5 };
}

function applyRatio(node: PaneNode, segments: string[], ratio: number): PaneNode {
  if (node.type === "leaf") return node;

  if (segments.length === 0) {
    return node.ratio === ratio ? node : { ...node, ratio };
  }

  const [head, ...rest] = segments;
  if (head !== "first" && head !== "second") return node;

  const child = applyRatio(node[head], rest, ratio);
  if (child === node[head]) return node;
  return { ...node, [head]: child };
}

function mapLeaf(node: PaneNode, targetLeafId: string, replace: (leaf: PaneLeafNode) => PaneNode): PaneNode {
  if (node.type === "leaf") return node.leafId === targetLeafId ? replace(node) : node;

  const first = mapLeaf(node.first, targetLeafId, replace);
  if (first !== node.first) return { ...node, first };

  const second = mapLeaf(node.second, targetLeafId, replace);
  if (second !== node.second) return { ...node, second };

  return node;
}

function containsLeaf(node: PaneNode, leafId: string): boolean {
  if (node.type === "leaf") return node.leafId === leafId;
  return containsLeaf(node.first, leafId) || containsLeaf(node.second, leafId);
}

function createLeafId() {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `pane:${randomPart}`;
}

import type { LayoutState, SplitMode, TerminalTab } from "../lib/types";

export type LayoutAction =
  | { type: "ADD_TAB"; tab: TerminalTab; activate?: boolean }
  | { type: "RENAME_TAB"; tabId: string; label: string }
  | { type: "CLOSE_TAB"; tabId: string; replacementTab?: TerminalTab }
  | { type: "ACTIVATE_PRIMARY"; tabId: string }
  | { type: "ACTIVATE_SECONDARY"; tabId: string }
  | {
      type: "ENABLE_SPLIT";
      orientation: Exclude<SplitMode, "none">;
      secondaryTabId?: string;
      secondaryTab?: TerminalTab;
    }
  | { type: "ROTATE_SPLIT" }
  | { type: "DISABLE_SPLIT" };

export function createLayoutState(tabs: TerminalTab[] = [], primaryTabId?: string | null): LayoutState {
  return normalizeLayout({
    tabs,
    primaryTabId: primaryTabId ?? tabs[0]?.id ?? null,
    secondaryTabId: null,
    split: "none",
    nestedSplit: null,
  });
}

export function layoutReducer(state: LayoutState, action: LayoutAction): LayoutState {
  switch (action.type) {
    case "ADD_TAB": {
      const tabs = state.tabs.some((tab) => tab.id === action.tab.id) ? state.tabs : [...state.tabs, action.tab];
      return normalizeLayout({
        ...state,
        tabs,
        primaryTabId: action.activate === false ? state.primaryTabId : action.tab.id,
      });
    }
    case "RENAME_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      const tabs = state.tabs.map((tab) => (tab.id === action.tabId ? { ...tab, label: action.label } : tab));
      return { ...state, tabs };
    }
    case "CLOSE_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return normalizeLayout(state);

      let tabs = state.tabs.filter((tab) => tab.id !== action.tabId);
      if (tabs.length === 0 && action.replacementTab) tabs = [action.replacementTab];

      let primaryTabId = state.primaryTabId === action.tabId ? tabs[0]?.id ?? null : state.primaryTabId;
      if (primaryTabId && !tabs.some((tab) => tab.id === primaryTabId)) primaryTabId = tabs[0]?.id ?? null;

      let secondaryTabId = state.secondaryTabId === action.tabId ? null : state.secondaryTabId;
      if (secondaryTabId && !tabs.some((tab) => tab.id === secondaryTabId)) secondaryTabId = null;

      let split = state.split;
      if (split !== "none") {
        if (!secondaryTabId || secondaryTabId === primaryTabId) {
          secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
        }
        if (!secondaryTabId) split = "none";
      }

      const nestedSplit = state.nestedSplit?.tabId === action.tabId ? null : state.nestedSplit;
      return normalizeLayout({ tabs, primaryTabId, secondaryTabId, split, nestedSplit });
    }
    case "ACTIVATE_PRIMARY": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayout({ ...state, primaryTabId: action.tabId });
    }
    case "ACTIVATE_SECONDARY": {
      if (state.split === "none" || !state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayout({ ...state, secondaryTabId: action.tabId });
    }
    case "ENABLE_SPLIT": {
      const tabs = action.secondaryTab && !state.tabs.some((tab) => tab.id === action.secondaryTab?.id)
        ? [...state.tabs, action.secondaryTab]
        : state.tabs;
      const primaryTabId = state.primaryTabId ?? tabs[0]?.id ?? null;
      if (state.split !== "none" && state.split !== action.orientation && primaryTabId) {
        return normalizeLayout({
          ...state,
          tabs,
          nestedSplit: {
            orientation: action.orientation,
            tabId: primaryTabId,
          },
        });
      }
      const requestedSecondaryId = action.secondaryTab?.id ?? action.secondaryTabId ?? null;
      const requestedExists = !!requestedSecondaryId && tabs.some((tab) => tab.id === requestedSecondaryId);
      const mirrorRequested = requestedExists && requestedSecondaryId === primaryTabId && tabs.length === 1;
      const secondaryTabId = mirrorRequested
        ? primaryTabId
        : requestedExists && requestedSecondaryId !== primaryTabId
          ? requestedSecondaryId
          : tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;

      return normalizeLayout({
        tabs,
        primaryTabId,
        secondaryTabId,
        split: secondaryTabId ? action.orientation : "none",
        nestedSplit: null,
      });
    }
    case "ROTATE_SPLIT":
      return normalizeLayout({
        ...state,
        split: state.split === "horizontal" ? "vertical" : state.split === "vertical" ? "horizontal" : "none",
        nestedSplit: null,
      });
    case "DISABLE_SPLIT":
      return normalizeLayout({ ...state, split: "none", secondaryTabId: null, nestedSplit: null });
  }
}

function normalizeLayout(state: LayoutState): LayoutState {
  const tabs = dedupeTabs(state.tabs);
  if (tabs.length === 0) {
    return { tabs: [], primaryTabId: null, secondaryTabId: null, split: "none", nestedSplit: null };
  }

  const primaryTabId = tabs.some((tab) => tab.id === state.primaryTabId) ? state.primaryTabId : tabs[0].id;
  let split = state.split;
  let secondaryTabId = tabs.some((tab) => tab.id === state.secondaryTabId) ? state.secondaryTabId : null;

  const isMirror = split !== "none" && tabs.length === 1 && secondaryTabId === primaryTabId;
  if (secondaryTabId === primaryTabId && !isMirror) {
    secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
  }

  if (split !== "none" && !secondaryTabId) {
    secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
  }

  if (split !== "none" && !secondaryTabId) split = "none";
  if (split === "none") secondaryTabId = null;
  const nestedSplit =
    split !== "none" &&
    state.nestedSplit &&
    state.nestedSplit.orientation !== split &&
    tabs.some((tab) => tab.id === state.nestedSplit?.tabId)
      ? state.nestedSplit
      : null;

  return { tabs, primaryTabId, secondaryTabId, split, nestedSplit };
}

function dedupeTabs(tabs: TerminalTab[]) {
  const seen = new Set<string>();
  return tabs.filter((tab) => {
    if (seen.has(tab.id)) return false;
    seen.add(tab.id);
    return true;
  });
}

export type WorktreeIdentity = {
  wsId: string;
  slug: string;
};

export type Worktree = {
  path: string;
  head: string;
  branch: string | null;
  bare: boolean;
  detached: boolean;
  locked: string | null;
  prunable: string | null;
};

export function worktreeIdentity(worktree: Worktree): WorktreeIdentity | null {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "");
  const parts = branch?.split("/");
  if (!parts || parts.length < 3 || parts[0] !== "orca") return null;

  return { wsId: parts[1], slug: parts.slice(2).join("/") };
}

export type DirtyFile = {
  statusCode: string;
  path: string;
};

export type DirtyState = {
  isDirty: boolean;
  files: DirtyFile[];
};

export type BranchDeletionPreview = {
  branch: string;
  head: string;
  upstream: string | null;
  merged: boolean;
  ahead: number | null;
  behind: number | null;
};

export type TerminalSignal = "interrupt" | "terminate" | "kill";

export type TerminalSessionSummary = {
  sessionId: string;
  worktreePath: string | null;
};

export type TerminalLifecycle = "starting" | "working" | "waiting" | "exited" | "failed";

export type TerminalSession = {
  id: string;
  cwd: string;
  workspaceId: string;
  worktree: WorktreeIdentity | null;
  backendSessionId: string | null;
  lifecycle: TerminalLifecycle;
  ownerId?: string | null;
  terminalTitle?: string | null;
};

export type TerminalTab = {
  id: string;
  label: string;
  sessionId: string;
};

export type Pane = {
  id: string;
  tabId: string;
};

export type SplitMode = "none" | "horizontal" | "vertical";

export type NestedSplit = {
  orientation: Exclude<SplitMode, "none">;
  tabId: string;
};

export type LayoutState = {
  tabs: TerminalTab[];
  primaryTabId: string | null;
  secondaryTabId: string | null;
  split: SplitMode;
  nestedSplit: NestedSplit | null;
};

export type AgentState = "starting" | "working" | "waiting" | "exited" | "failed";

export type ActiveAgent = {
  id: string;
  name: string;
  task: string;
  state: AgentState;
  worktree: WorktreeIdentity | null;
  worktreePath: string;
  sessionId: string;
};

export type TerminalOutputPayload = {
  sessionId: string;
  data: string;
};

export type TerminalLifecyclePayload = {
  sessionId: string;
  state: "started" | "exited" | "failed";
  exitCode: number | null;
  reason: string | null;
};

export type WorktreeChangedPayload = {
  workspaceId: string;
  worktree: WorktreeIdentity;
  kind: "created" | "deleted" | "destructivelyDeleted" | "dirtyChanged" | "pruned";
};

export type StructuredIpcError = {
  code: string;
  message: string;
  details?: Record<string, unknown>;
};

import { useCallback, useEffect, useReducer, useRef } from "react";

import { formatTabLabelFromTitle, parseAgentTitle } from "../lib/agentTitle";
import { closeTerminal, DEFAULT_WORKSPACE_ID, spawnTerminal } from "../lib/tauri";
import { ensureTerminalEvents, terminalEventBus } from "../lib/terminalEvents";
import { worktreeIdentity } from "../lib/types";
import type {
  ActiveAgent,
  LayoutState,
  SplitMode,
  TerminalLifecycle,
  TerminalLifecyclePayload,
  TerminalSession,
  TerminalTab,
  Worktree,
  WorktreeIdentity,
} from "../lib/types";
import { createLayoutState, layoutReducer } from "./layout";

const LAST_TAB_EXIT_TIMEOUT_MS = 5_000;

export type WorkspaceState = {
  worktrees: Worktree[];
  activeWorktreePath: string | null;
  sessions: Record<string, TerminalSession>;
  layout: LayoutState;
};

export type WorkspaceServices = {
  ensureTerminalEvents: () => Promise<void>;
  spawnTerminal: (request: { workspaceId: string; worktree: WorktreeIdentity | null }) => Promise<string>;
  closeTerminal: (sessionId: string) => Promise<void>;
  waitForTerminalExit: (sessionId: string, timeoutMs: number) => Promise<void>;
};

type WorkspaceAction =
  | { type: "SET_WORKTREES"; worktrees: Worktree[] }
  | { type: "SELECT_WORKTREE"; path: string }
  | { type: "ADD_TAB_WITH_SESSION"; tab: TerminalTab; session: TerminalSession }
  | { type: "UPDATE_TAB_TITLE"; tabId: string; title: string }
  | { type: "ENABLE_SPLIT_EXISTING"; tabId: string; orientation: Exclude<SplitMode, "none"> }
  | {
      type: "CLOSE_TAB";
      tabId: string;
      replacement?: { tab: TerminalTab; session: TerminalSession };
    }
  | { type: "ACTIVATE_PRIMARY"; tabId: string }
  | { type: "ACTIVATE_SECONDARY"; tabId: string }
  | { type: "ROTATE_SPLIT" }
  | { type: "DISABLE_SPLIT" }
  | { type: "SESSION_LIFECYCLE"; backendSessionId: string; lifecycle: TerminalLifecycle };

type UseWorkspaceStoreOptions = {
  workspaceId?: string;
  initialWorktrees?: Worktree[];
  services?: WorkspaceServices;
};

const defaultServices: WorkspaceServices = {
  ensureTerminalEvents,
  spawnTerminal,
  closeTerminal,
  waitForTerminalExit,
};

export function useWorkspaceStore({
  workspaceId = DEFAULT_WORKSPACE_ID,
  initialWorktrees = [],
  services = defaultServices,
}: UseWorkspaceStoreOptions = {}) {
  const [state, reactDispatch] = useReducer(workspaceReducer, initialWorktrees, createInitialState);
  const stateRef = useRef(state);
  stateRef.current = state;

  const dispatch = useCallback((action: WorkspaceAction) => {
    stateRef.current = workspaceReducer(stateRef.current, action);
    reactDispatch(action);
  }, []);

  useEffect(
    () =>
      terminalEventBus.subscribeLifecycle((payload) => {
        dispatch({
          type: "SESSION_LIFECYCLE",
          backendSessionId: payload.sessionId,
          lifecycle: mapBackendLifecycle(payload),
        });
      }),
    [dispatch],
  );

  const createSpawnedTab = useCallback(
    async (worktree: Worktree, label?: string) => {
      await services.ensureTerminalEvents();
      const backendSessionId = await services.spawnTerminal({
        workspaceId,
        worktree: worktreeIdentity(worktree),
      });
      const sessionId = createId("session");
      const tabId = createId("tab");
      const session: TerminalSession = {
        id: sessionId,
        cwd: worktree.path,
        workspaceId,
        worktree: worktreeIdentity(worktree),
        backendSessionId,
        lifecycle: "working",
        terminalTitle: null,
      };
      const tab: TerminalTab = {
        id: tabId,
        label: label ?? nextTabLabel(worktree, stateRef.current.layout.tabs, stateRef.current.sessions),
        sessionId,
      };
      return { tab, session };
    },
    [services, workspaceId],
  );

  const openTab = useCallback(
    async (worktree: Worktree) => {
      const existingTab = stateRef.current.layout.tabs.find(
        (tab) => stateRef.current.sessions[tab.sessionId]?.cwd === worktree.path,
      );
      if (existingTab) {
        const existingSession = stateRef.current.sessions[existingTab.sessionId];
        const tab: TerminalTab = {
          id: createId("tab"),
          label: nextTabLabel(worktree, stateRef.current.layout.tabs, stateRef.current.sessions),
          sessionId: existingSession.id,
        };
        dispatch({ type: "ADD_TAB_WITH_SESSION", tab, session: existingSession });
        dispatch({ type: "SELECT_WORKTREE", path: worktree.path });
        return tab.id;
      }

      const binding = await createSpawnedTab(worktree);
      dispatch({ type: "ADD_TAB_WITH_SESSION", ...binding });
      if (!stateRef.current.worktrees.some((candidate) => candidate.path === worktree.path)) {
        dispatch({ type: "SET_WORKTREES", worktrees: [...stateRef.current.worktrees, worktree] });
      }
      dispatch({ type: "SELECT_WORKTREE", path: worktree.path });
      return binding.tab.id;
    },
    [createSpawnedTab, dispatch],
  );

  const ensureTabForWorktree = useCallback(
    async (worktree: Worktree) => {
      const snapshot = stateRef.current;
      const existing = snapshot.layout.tabs.find((tab) => snapshot.sessions[tab.sessionId]?.cwd === worktree.path);
      dispatch({ type: "SELECT_WORKTREE", path: worktree.path });
      if (existing) {
        dispatch({ type: "ACTIVATE_PRIMARY", tabId: existing.id });
        return existing.id;
      }
      return openTab(worktree);
    },
    [dispatch, openTab],
  );

  const updateTabTitle = useCallback(
    (tabId: string, title: string) => {
      dispatch({ type: "UPDATE_TAB_TITLE", tabId, title });
    },
    [dispatch],
  );

  const enableSplit = useCallback(
    async (orientation: Exclude<SplitMode, "none"> = "horizontal") => {
      let snapshot = stateRef.current;
      if (!snapshot.layout.primaryTabId) {
        const activeWorktree = getActiveWorktree(snapshot);
        if (!activeWorktree) return;
        await openTab(activeWorktree);
        snapshot = stateRef.current;
      }

      const primaryTabId = snapshot.layout.primaryTabId;
      if (!primaryTabId) return;
      const existingSecondary = snapshot.layout.tabs.find((tab) => tab.id !== primaryTabId);
      dispatch({
        type: "ENABLE_SPLIT_EXISTING",
        tabId: existingSecondary?.id ?? primaryTabId,
        orientation,
      });
    },
    [dispatch, openTab],
  );

  const closeTab = useCallback(
    async (tabId: string) => {
      const snapshot = stateRef.current;
      const closingTab = snapshot.layout.tabs.find((tab) => tab.id === tabId);
      if (!closingTab) return;
      const closingSession = snapshot.sessions[closingTab.sessionId];
      const sessionIsShared = snapshot.layout.tabs.some(
        (tab) => tab.id !== tabId && tab.sessionId === closingTab.sessionId,
      );

      if (sessionIsShared) {
        dispatch({ type: "CLOSE_TAB", tabId });
        return;
      }

      if (snapshot.layout.tabs.length === 1) {
        const worktree =
          (closingSession && snapshot.worktrees.find((candidate) => candidate.path === closingSession.cwd)) ??
          getActiveWorktree(snapshot);
        if (!worktree) return;

        await closeBackendSessionAndWait(closingSession, services);
        const replacement = await createSpawnedTab(worktree, closingTab.label);
        dispatch({ type: "CLOSE_TAB", tabId, replacement });
        return;
      }

      dispatch({ type: "CLOSE_TAB", tabId });
      await closeBackendSession(closingSession, services);
    },
    [createSpawnedTab, dispatch, services],
  );

  const syncWorktrees = useCallback(
    async (worktrees: Worktree[]) => {
      const snapshot = stateRef.current;
      const validWorktreePaths = new Set(worktrees.map((worktree) => worktree.path));
      const staleSessions = Object.values(snapshot.sessions).filter((session) => !validWorktreePaths.has(session.cwd));
      dispatch({ type: "SET_WORKTREES", worktrees });
      await Promise.allSettled(staleSessions.map((session) => closeBackendSession(session, services)));
    },
    [dispatch, services],
  );

  const rotateSplit = useCallback(() => dispatch({ type: "ROTATE_SPLIT" }), [dispatch]);
  const disableSplit = useCallback(() => dispatch({ type: "DISABLE_SPLIT" }), [dispatch]);
  const activatePrimary = useCallback((tabId: string) => dispatch({ type: "ACTIVATE_PRIMARY", tabId }), [dispatch]);
  const activateSecondary = useCallback((tabId: string) => dispatch({ type: "ACTIVATE_SECONDARY", tabId }), [dispatch]);

  return {
    state,
    agents: selectAgents(state),
    openTab,
    ensureTabForWorktree,
    updateTabTitle,
    closeTab,
    enableSplit,
    rotateSplit,
    disableSplit,
    activatePrimary,
    activateSecondary,
    syncWorktrees,
  };
}

export function selectAgents(state: WorkspaceState): ActiveAgent[] {
  return state.layout.tabs.flatMap((tab) => {
    const session = state.sessions[tab.sessionId];
    if (!session) return [];
    const worktree = state.worktrees.find((candidate) => candidate.path === session.cwd);
    const parsed = parseAgentTitle(session.terminalTitle || tab.label);
    const isExplicitAgent = parsed?.isAgent === true;
    const name = isExplicitAgent ? parsed.name : tab.label;
    const task = isExplicitAgent ? parsed.task : (worktree?.branch?.replace(/^refs\/heads\//, "") ?? session.cwd);
    const agentState = isExplicitAgent ? parsed.state : session.lifecycle;

    return [
      {
        id: session.backendSessionId ?? session.id,
        name,
        task,
        state: agentState,
        worktree: session.worktree,
        worktreePath: worktree?.path ?? session.cwd,
        sessionId: session.backendSessionId ?? session.id,
      },
    ];
  });
}

function createInitialState(worktrees: Worktree[]): WorkspaceState {
  return {
    worktrees,
    activeWorktreePath: worktrees[0]?.path ?? null,
    sessions: {},
    layout: createLayoutState(),
  };
}

function workspaceReducer(state: WorkspaceState, action: WorkspaceAction): WorkspaceState {
  switch (action.type) {
    case "SET_WORKTREES": {
      const validWorktreePaths = new Set(action.worktrees.map((worktree) => worktree.path));
      const sessions = Object.fromEntries(
        Object.entries(state.sessions).filter(([, session]) => validWorktreePaths.has(session.cwd)),
      );
      let layout = state.layout;
      for (const tab of state.layout.tabs) {
        if (!sessions[tab.sessionId]) layout = layoutReducer(layout, { type: "CLOSE_TAB", tabId: tab.id });
      }
      const activeWorktreePath = action.worktrees.some((worktree) => worktree.path === state.activeWorktreePath)
        ? state.activeWorktreePath
        : action.worktrees[0]?.path ?? null;
      return { ...state, worktrees: action.worktrees, activeWorktreePath, sessions, layout };
    }
    case "SELECT_WORKTREE":
      return state.worktrees.some((worktree) => worktree.path === action.path)
        ? { ...state, activeWorktreePath: action.path }
        : state;
    case "ADD_TAB_WITH_SESSION":
      return {
        ...state,
        sessions: { ...state.sessions, [action.session.id]: action.session },
        layout: layoutReducer(state.layout, { type: "ADD_TAB", tab: action.tab }),
      };
    case "UPDATE_TAB_TITLE": {
      const targetTab = state.layout.tabs.find((tab) => tab.id === action.tabId);
      if (!targetTab) return state;
      const session = state.sessions[targetTab.sessionId];
      const newLabel = formatTabLabelFromTitle(action.title, targetTab.label);
      const sessions = session
        ? { ...state.sessions, [session.id]: { ...session, terminalTitle: action.title } }
        : state.sessions;
      const layout = layoutReducer(state.layout, {
        type: "RENAME_TAB",
        tabId: action.tabId,
        label: newLabel,
      });
      return { ...state, sessions, layout };
    }
    case "ENABLE_SPLIT_EXISTING":
      return {
        ...state,
        layout: layoutReducer(state.layout, {
          type: "ENABLE_SPLIT",
          orientation: action.orientation,
          secondaryTabId: action.tabId,
        }),
      };
    case "CLOSE_TAB": {
      const closingTab = state.layout.tabs.find((tab) => tab.id === action.tabId);
      const sessions = { ...state.sessions };
      const sharedSession = closingTab
        ? state.layout.tabs.some((tab) => tab.id !== action.tabId && tab.sessionId === closingTab.sessionId)
        : false;
      if (closingTab && !sharedSession) delete sessions[closingTab.sessionId];
      if (action.replacement) sessions[action.replacement.session.id] = action.replacement.session;
      return {
        ...state,
        sessions,
        layout: layoutReducer(state.layout, {
          type: "CLOSE_TAB",
          tabId: action.tabId,
          replacementTab: action.replacement?.tab,
        }),
      };
    }
    case "ACTIVATE_PRIMARY":
      return { ...state, layout: layoutReducer(state.layout, { type: "ACTIVATE_PRIMARY", tabId: action.tabId }) };
    case "ACTIVATE_SECONDARY":
      return { ...state, layout: layoutReducer(state.layout, { type: "ACTIVATE_SECONDARY", tabId: action.tabId }) };
    case "ROTATE_SPLIT":
      return { ...state, layout: layoutReducer(state.layout, { type: "ROTATE_SPLIT" }) };
    case "DISABLE_SPLIT":
      return { ...state, layout: layoutReducer(state.layout, { type: "DISABLE_SPLIT" }) };
    case "SESSION_LIFECYCLE": {
      const sessions = Object.fromEntries(
        Object.entries(state.sessions).map(([id, session]) => [
          id,
          session.backendSessionId === action.backendSessionId ? { ...session, lifecycle: action.lifecycle } : session,
        ]),
      );
      return { ...state, sessions };
    }
  }
}

async function closeBackendSession(session: TerminalSession | undefined, services: WorkspaceServices) {
  if (!session?.backendSessionId) return;
  try {
    await services.closeTerminal(session.backendSessionId);
  } finally {
    terminalEventBus.clearSession(session.backendSessionId);
  }
}

async function closeBackendSessionAndWait(session: TerminalSession | undefined, services: WorkspaceServices) {
  if (!session?.backendSessionId) return;
  const backendSessionId = session.backendSessionId;
  const exitPromise = services.waitForTerminalExit(backendSessionId, LAST_TAB_EXIT_TIMEOUT_MS);
  try {
    await services.closeTerminal(backendSessionId);
    await exitPromise;
  } finally {
    terminalEventBus.clearSession(backendSessionId);
  }
}

function waitForTerminalExit(sessionId: string, timeoutMs: number) {
  return new Promise<void>((resolve) => {
    let timer: ReturnType<typeof setTimeout>;
    const unsubscribe = terminalEventBus.subscribeLifecycle((payload) => {
      if (payload.sessionId !== sessionId || (payload.state !== "exited" && payload.state !== "failed")) return;
      clearTimeout(timer);
      unsubscribe();
      resolve();
    });
    timer = setTimeout(() => {
      unsubscribe();
      resolve();
    }, timeoutMs);
  });
}

function getActiveWorktree(state: WorkspaceState) {
  return state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? state.worktrees[0] ?? null;
}

function nextTabLabel(worktree: Worktree, tabs: TerminalTab[], sessions: Record<string, TerminalSession>) {
  const base = worktree.path === "." ? "main" : worktree.path.split(/[\\/]/).filter(Boolean).at(-1) ?? worktree.path;
  const count = tabs.filter((tab) => sessions[tab.sessionId]?.cwd === worktree.path).length + 1;
  return count === 1 ? base : `${base} (${count})`;
}

function mapBackendLifecycle(payload: TerminalLifecyclePayload): TerminalLifecycle {
  if (payload.state === "started") return "working";
  if (payload.state === "failed") return "failed";
  return "exited";
}

function createId(prefix: string) {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}:${randomPart}`;
}

import { describe, expect, it } from "vitest";

import type { TerminalTab } from "../lib/types";
import { createLayoutState, layoutReducer } from "./layout";

function tab(id: string, sessionId: string): TerminalTab {
  return { id, label: id, sessionId };
}

describe("layoutReducer", () => {
  it("enables a single-tab mirror split without adding another logical tab", () => {
    const primary = tab("tab-1", "session-1");
    const state = createLayoutState([primary], primary.id);

    const next = layoutReducer(state, {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: primary.id,
    });

    expect(next.tabs).toEqual([primary]);
    expect(next.primaryTabId).toBe(primary.id);
    expect(next.secondaryTabId).toBe(primary.id);
    expect(next.split).toBe("horizontal");
  });

  it("uses an existing other tab as the secondary pane when available", () => {
    const primary = tab("tab-1", "session-1");
    const secondary = tab("tab-2", "session-2");
    const state = createLayoutState([primary, secondary], primary.id);

    const next = layoutReducer(state, {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: secondary.id,
    });

    expect(next.tabs).toEqual([primary, secondary]);
    expect(next.primaryTabId).toBe(primary.id);
    expect(next.secondaryTabId).toBe(secondary.id);
    expect(next.split).toBe("horizontal");
  });

  it("keeps a horizontal split when adding a vertical nested split", () => {
    const primary = tab("tab-1", "session-1");
    const secondary = tab("tab-2", "session-2");
    const horizontal = layoutReducer(createLayoutState([primary, secondary], primary.id), {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: secondary.id,
    });

    const nested = layoutReducer(horizontal, {
      type: "ENABLE_SPLIT",
      orientation: "vertical",
      secondaryTabId: primary.id,
    });

    expect(nested).toMatchObject({
      primaryTabId: primary.id,
      secondaryTabId: secondary.id,
      split: "horizontal",
      nestedSplit: {
        orientation: "vertical",
        tabId: primary.id,
      },
    });
  });

  it("rotates split orientation without changing tab identity", () => {
    const primary = tab("tab-1", "session-1");
    const split = layoutReducer(createLayoutState([primary], primary.id), {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: primary.id,
    });

    const rotated = layoutReducer(split, { type: "ROTATE_SPLIT" });

    expect(rotated.split).toBe("vertical");
    expect(rotated.tabs).toEqual(split.tabs);
    expect(rotated.primaryTabId).toBe(split.primaryTabId);
    expect(rotated.secondaryTabId).toBe(split.secondaryTabId);
  });

  it("applies the last-tab-close replacement policy atomically", () => {
    const primary = tab("tab-1", "session-1");
    const replacement = tab("tab-2", "session-2");
    const state = createLayoutState([primary], primary.id);

    const next = layoutReducer(state, {
      type: "CLOSE_TAB",
      tabId: primary.id,
      replacementTab: replacement,
    });

    expect(next.tabs).toEqual([replacement]);
    expect(next.primaryTabId).toBe(replacement.id);
    expect(next.secondaryTabId).toBeNull();
    expect(next.split).toBe("none");
  });

  it("never leaves stale split ids when the secondary tab closes", () => {
    const primary = tab("tab-1", "session-1");
    const secondary = tab("tab-2", "session-2");
    const split = layoutReducer(createLayoutState([primary, secondary], primary.id), {
      type: "ENABLE_SPLIT",
      orientation: "horizontal",
      secondaryTabId: secondary.id,
    });

    const next = layoutReducer(split, { type: "CLOSE_TAB", tabId: secondary.id });

    expect(next.tabs).toEqual([primary]);
    expect(next.primaryTabId).toBe(primary.id);
    expect(next.secondaryTabId).toBeNull();
    expect(next.split).toBe("none");
  });

  it("renames tab label cleanly without touching other tabs or split state", () => {
    const primary = tab("tab-1", "session-1");
    const secondary = tab("tab-2", "session-2");
    const state = createLayoutState([primary, secondary], primary.id);

    const renamed = layoutReducer(state, {
      type: "RENAME_TAB",
      tabId: "tab-1",
      label: "omo: build",
    });

    expect(renamed.tabs[0].label).toBe("omo: build");
    expect(renamed.tabs[1].label).toBe("tab-2");
    expect(renamed.primaryTabId).toBe("tab-1");
  });
});

import { act, renderHook } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import type { Worktree } from "../lib/types";
import { useWorkspaceStore, type WorkspaceServices } from "./workspaceStore";

const worktree: Worktree = {
  path: "/repo/main",
  head: "abc123",
  branch: "refs/heads/orca/ws-main/main",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

const featureWorktree: Worktree = {
  ...worktree,
  path: "/repo/feature",
  branch: "refs/heads/orca/ws-main/feature",
};

type ExitDeferred = {
  promise: Promise<void>;
  resolve: () => void;
};

function createServices({ autoConfirmExit = true }: { autoConfirmExit?: boolean } = {}) {
  let sessionNumber = 0;
  const activeByWorktree = new Map<string, string>();
  const worktreeBySession = new Map<string, string>();
  const exits = new Map<string, ExitDeferred>();

  const getExit = (sessionId: string) => {
    const existing = exits.get(sessionId);
    if (existing) return existing;
    let resolve!: () => void;
    const promise = new Promise<void>((done) => {
      resolve = done;
    });
    const deferred = { promise, resolve };
    exits.set(sessionId, deferred);
    return deferred;
  };

  const confirmExit = (sessionId: string) => {
    const key = worktreeBySession.get(sessionId);
    if (key && activeByWorktree.get(key) === sessionId) activeByWorktree.delete(key);
    worktreeBySession.delete(sessionId);
    const deferred = getExit(sessionId);
    exits.delete(sessionId);
    deferred.resolve();
  };

  const services: WorkspaceServices = {
    ensureTerminalEvents: vi.fn(async () => undefined),
    spawnTerminal: vi.fn(async (request) => {
      const key = `${request.workspaceId}:${request.worktree?.wsId ?? "root"}:${request.worktree?.slug ?? "root"}`;
      if (activeByWorktree.has(key)) {
        throw { code: "WRITER_ALREADY_ACTIVE", message: "writer already active", details: { worktree: request.worktree } };
      }
      const sessionId = `backend-${++sessionNumber}`;
      activeByWorktree.set(key, sessionId);
      worktreeBySession.set(sessionId, key);
      return sessionId;
    }),
    closeTerminal: vi.fn(async (sessionId) => {
      const deferred = getExit(sessionId);
      if (autoConfirmExit) queueMicrotask(() => confirmExit(sessionId));
      await deferred.promise;
    }),
    waitForTerminalExit: vi.fn(async (sessionId) => {
      await getExit(sessionId).promise;
    }),
  };

  return { services, confirmExit };
}

describe("useWorkspaceStore terminal ownership", () => {
  it("enables a single-tab mirror split without spawning another backend PTY", async () => {
    const { services } = createServices();
    const { result } = renderHook(() => useWorkspaceStore({ initialWorktrees: [worktree], services }));

    await act(async () => {
      await result.current.openTab(worktree);
    });
    vi.mocked(services.spawnTerminal).mockClear();

    await act(async () => {
      await result.current.enableSplit("horizontal");
    });

    expect(result.current.state.layout.tabs).toHaveLength(1);
    expect(result.current.state.layout.secondaryTabId).toBe(result.current.state.layout.primaryTabId);
    expect(result.current.state.layout.split).toBe("horizontal");
    expect(services.spawnTerminal).not.toHaveBeenCalled();
  });

  it("adds a same-worktree terminal tab as a mirror without another backend PTY", async () => {
    const { services } = createServices();
    const { result } = renderHook(() => useWorkspaceStore({ initialWorktrees: [worktree], services }));

    await act(async () => {
      await result.current.openTab(worktree);
      await result.current.openTab(worktree);
    });

    const tabs = result.current.state.layout.tabs;
    expect(tabs).toHaveLength(2);
    expect(new Set(tabs.map((tab) => tab.sessionId)).size).toBe(1);
    expect(services.spawnTerminal).toHaveBeenCalledTimes(1);

    await act(async () => {
      await result.current.closeTab(tabs[1].id);
    });

    expect(result.current.state.layout.tabs).toHaveLength(1);
    expect(services.closeTerminal).not.toHaveBeenCalled();
  });

  it("preserves backend session ids when only split orientation changes", async () => {
    const { services } = createServices();
    const { result } = renderHook(() => useWorkspaceStore({ initialWorktrees: [worktree], services }));

    await act(async () => {
      await result.current.openTab(worktree);
      await result.current.enableSplit("horizontal");
    });

    const before = Object.values(result.current.state.sessions).map((session) => session.backendSessionId);
    act(() => result.current.rotateSplit());
    const after = Object.values(result.current.state.sessions).map((session) => session.backendSessionId);

    expect(result.current.state.layout.split).toBe("vertical");
    expect(after).toEqual(before);
    expect(services.spawnTerminal).toHaveBeenCalledTimes(1);
  });

  it("spawns a last-tab replacement only after lifecycle-confirmed writer release", async () => {
    const { services, confirmExit } = createServices({ autoConfirmExit: false });
    const { result } = renderHook(() => useWorkspaceStore({ initialWorktrees: [worktree], services }));

    await act(async () => {
      await result.current.openTab(worktree);
    });
    const closingTabId = result.current.state.layout.primaryTabId!;
    const closingSessionId = result.current.state.layout.tabs[0].sessionId;
    const closingBackendId = result.current.state.sessions[closingSessionId].backendSessionId!;

    const closePromise = result.current.closeTab(closingTabId);
    await vi.waitFor(() => expect(services.closeTerminal).toHaveBeenCalledWith(closingBackendId));

    expect(services.waitForTerminalExit).toHaveBeenCalledWith(closingBackendId, 5_000);
    expect(services.spawnTerminal).toHaveBeenCalledTimes(1);
    expect(vi.mocked(services.waitForTerminalExit).mock.invocationCallOrder[0]).toBeLessThan(
      vi.mocked(services.closeTerminal).mock.invocationCallOrder[0],
    );

    confirmExit(closingBackendId);
    await act(async () => {
      await closePromise;
    });

    expect(result.current.state.layout.tabs).toHaveLength(1);
    expect(result.current.state.layout.primaryTabId).toBe(result.current.state.layout.tabs[0].id);
    expect(result.current.state.layout.tabs[0].id).not.toBe(closingTabId);
    expect(result.current.state.layout.secondaryTabId).toBeNull();
    expect(services.spawnTerminal).toHaveBeenCalledTimes(2);
    expect(vi.mocked(services.closeTerminal).mock.invocationCallOrder[0]).toBeLessThan(
      vi.mocked(services.spawnTerminal).mock.invocationCallOrder[1],
    );
  });

  it("keeps layout invariants valid when the secondary tab closes", async () => {
    const { services } = createServices();
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [worktree, featureWorktree], services }),
    );

    await act(async () => {
      await result.current.openTab(worktree);
      await result.current.openTab(featureWorktree);
      await result.current.enableSplit("horizontal");
    });
    const secondaryTabId = result.current.state.layout.secondaryTabId!;

    await act(async () => {
      await result.current.closeTab(secondaryTabId);
    });

    expect(result.current.state.layout.tabs).toHaveLength(1);
    expect(result.current.state.layout.primaryTabId).toBe(result.current.state.layout.tabs[0].id);
    expect(result.current.state.layout.secondaryTabId).toBeNull();
    expect(result.current.state.layout.split).toBe("none");
  });

  it("derives visible agents only from live terminal session metadata", async () => {
    const { services } = createServices();
    const { result } = renderHook(() => useWorkspaceStore({ initialWorktrees: [worktree], services }));

    expect(result.current.agents).toEqual([]);
    await act(async () => {
      await result.current.openTab(worktree);
    });

    expect(result.current.agents).toEqual([
      expect.objectContaining({
        id: "backend-1",
        sessionId: "backend-1",
        state: "working",
        worktree: { wsId: "ws-main", slug: "main" },
        worktreePath: worktree.path,
        task: "orca/ws-main/main",
      }),
    ]);
  });

  it("removes deleted-worktree tabs, sessions, and agents during synchronization", async () => {
    const { services } = createServices();
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [worktree, featureWorktree], services }),
    );

    await act(async () => {
      await result.current.openTab(worktree);
      await result.current.openTab(featureWorktree);
    });
    expect(result.current.agents).toHaveLength(2);

    await act(async () => {
      await result.current.syncWorktrees([worktree]);
    });

    expect(result.current.state.worktrees).toEqual([worktree]);
    expect(Object.values(result.current.state.sessions).every((session) => session.cwd === worktree.path)).toBe(true);
    expect(result.current.state.layout.tabs).toHaveLength(1);
    expect(result.current.agents).toHaveLength(1);
    expect(services.closeTerminal).toHaveBeenCalledWith("backend-2");
  });

  it("auto-renames tab label and detects OMO agent when terminal title changes", async () => {
    const { services } = createServices();
    const { result } = renderHook(() => useWorkspaceStore({ initialWorktrees: [worktree], services }));

    await act(async () => {
      await result.current.openTab(worktree);
    });
    const tabId = result.current.state.layout.tabs[0].id;
    expect(result.current.state.layout.tabs[0].label).toBe("main");

    act(() => {
      result.current.updateTabTitle(tabId, "⠋ omo: refactoring terminal UI");
    });

    expect(result.current.state.layout.tabs[0].label).toBe("omo: refactoring terminal UI");
    expect(result.current.agents).toEqual([
      expect.objectContaining({
        name: "OMO",
        task: "refactoring terminal UI",
        state: "working",
      }),
    ]);

    act(() => {
      result.current.updateTabTitle(tabId, "omo: waiting for user confirmation");
    });

    expect(result.current.state.layout.tabs[0].label).toBe("omo: waiting for user confirmation");
    expect(result.current.agents).toEqual([
      expect.objectContaining({
        name: "OMO",
        task: "waiting for user confirmation",
        state: "waiting",
      }),
    ]);
  });
});

import { useCallback, useEffect, useMemo, useState } from "react";

import { CommandPalette } from "./components/CommandPalette";
import { AddProjectDialog, AddWorktreeDialog } from "./components/ProjectDialogs";
import { SettingsDialog } from "./components/SettingsDialog";
import { Sidebar } from "./components/Sidebar";
import { TerminalSplitView } from "./components/TerminalSplitView";
import { WorktreeDeleteDialog } from "./components/WorktreeDeleteDialog";
import { useShortcuts } from "./lib/shortcuts";
import { DEFAULT_WORKSPACE_ID, getWorktreeStatus, registerProject, type RegisteredProject } from "./lib/tauri";
import { worktreeIdentity, type DirtyState, type Worktree } from "./lib/types";
import { useWorkspaceRuntime } from "./state/workspaceRuntime";
import { useWorkspaceStore } from "./state/workspaceStore";

const PROJECTS_STORAGE_KEY = "rorca.projects";
const ACTIVE_PROJECT_STORAGE_KEY = "rorca.active-project";
export const SIDEBAR_OPEN_STORAGE_KEY = "orca.sidebar.open";
const DEFAULT_PROJECT: RegisteredProject = { workspaceId: DEFAULT_WORKSPACE_ID, repoRoot: "." };

export function App() {
  const [projects, setProjects] = useState<RegisteredProject[]>(loadProjects);
  const [activeProjectId, setActiveProjectId] = useState(loadActiveProjectId);
  const activeProject = useMemo(
    () => projects.find((project) => project.workspaceId === activeProjectId) ?? projects[0] ?? DEFAULT_PROJECT,
    [activeProjectId, projects],
  );

  const {
    state,
    agents,
    openTab,
    ensureTabForWorktree,
    closeTab,
    enableSplit,
    disableSplit,
    updateTabTitle,
    activatePrimary,
    syncWorktrees,
  } = useWorkspaceStore({ workspaceId: activeProject.workspaceId });
  const { runtimeError, refreshWorktrees, reportRuntimeError } = useWorkspaceRuntime({
    workspaceId: activeProject.workspaceId,
    activeWorktreePath: state.activeWorktreePath,
    syncWorktrees,
    ensureTabForWorktree,
  });

  useEffect(() => {
    void registerProject({
      workspaceId: activeProject.workspaceId,
      repoPath: activeProject.repoRoot,
    })
      .then(() => refreshWorktrees())
      .catch(reportRuntimeError);
  }, [activeProject.repoRoot, activeProject.workspaceId, refreshWorktrees, reportRuntimeError]);

  const [isAddProjectOpen, setIsAddProjectOpen] = useState(false);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(loadSidebarOpen);
  const [deleteTarget, setDeleteTarget] = useState<Worktree | null>(null);
  const [worktreeStatuses, setWorktreeStatuses] = useState<Record<string, DirtyState | undefined>>({});

  const toggleSidebar = useCallback(() => {
    setIsSidebarOpen((current) => {
      const next = !current;
      persistSidebarOpen(next);
      return next;
    });
  }, []);

  const activeWorktree = useMemo(
    () => state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? null,
    [state.activeWorktreePath, state.worktrees],
  );

  const handleSelectProject = useCallback(
    (project: RegisteredProject) => {
      if (project.workspaceId === activeProject.workspaceId) return;
      setActiveProjectId(project.workspaceId);
      persistActiveProjectId(project.workspaceId);
      setWorktreeStatuses({});
      setDeleteTarget(null);
    },
    [activeProject.workspaceId],
  );

  const handleRegisteredProject = useCallback((project: RegisteredProject) => {
    setProjects((current) => {
      const next = [...current.filter((candidate) => candidate.workspaceId !== project.workspaceId), project];
      persistProjects(next);
      return next;
    });
    setActiveProjectId(project.workspaceId);
    persistActiveProjectId(project.workspaceId);
    setWorktreeStatuses({});
  }, []);

  const handleSelectWorktree = useCallback(
    (worktree: Worktree) => {
      // A worktree selected from another project's tree must switch the active project first,
      // because the workspace store only ever holds the active project's worktrees.
      const ownerId = worktreeIdentity(worktree)?.wsId;
      const owner = ownerId ? projects.find((project) => project.workspaceId === ownerId) : undefined;
      if (owner && owner.workspaceId !== activeProject.workspaceId) {
        handleSelectProject(owner);
        return;
      }
      void ensureTabForWorktree(worktree).catch(reportRuntimeError);
    },
    [activeProject.workspaceId, ensureTabForWorktree, handleSelectProject, projects, reportRuntimeError],
  );

  const handleSelectTerminalTab = useCallback(
    (tabId: string) => {
      const tab = state.layout.tabs.find((candidate) => candidate.id === tabId);
      const session = tab ? state.sessions[tab.sessionId] : undefined;
      const worktree = session ? state.worktrees.find((candidate) => candidate.path === session.cwd) : undefined;
      if (!worktree || worktree.path === state.activeWorktreePath) {
        activatePrimary(tabId);
        return;
      }
      void ensureTabForWorktree(worktree)
        .then(() => activatePrimary(tabId))
        .catch(reportRuntimeError);
    },
    [activatePrimary, ensureTabForWorktree, reportRuntimeError, state.activeWorktreePath, state.layout.tabs, state.sessions, state.worktrees],
  );

  const handleRefreshWorktreeStatus = useCallback(
    (worktree: Worktree) => {
      const identity = worktreeIdentity(worktree);
      if (!identity) return;
      void getWorktreeStatus({ workspaceId: activeProject.workspaceId, worktree: identity })
        .then((status) => {
          setWorktreeStatuses((current) => ({ ...current, [worktree.path]: status }));
        })
        .catch(reportRuntimeError);
    },
    [activeProject.workspaceId, reportRuntimeError],
  );

  const handleAddTerminalTab = useCallback(() => {
    if (!activeWorktree) return;
    void openTab(activeWorktree).catch(reportRuntimeError);
  }, [activeWorktree, openTab, reportRuntimeError]);

  const handleCloseTab = useCallback(
    (tabId: string) => {
      void closeTab(tabId).catch(reportRuntimeError);
    },
    [closeTab, reportRuntimeError],
  );

  const handleCycleTab = useCallback(
    (offset: number) => {
      const tabs = state.layout.tabs;
      if (tabs.length < 2) return;
      const currentIndex = Math.max(0, tabs.findIndex((tab) => tab.id === state.layout.primaryTabId));
      const nextIndex = (currentIndex + offset + tabs.length) % tabs.length;
      handleSelectTerminalTab(tabs[nextIndex].id);
    },
    [handleSelectTerminalTab, state.layout.primaryTabId, state.layout.tabs],
  );

  const splitRight = useCallback(() => {
    void enableSplit("horizontal").catch(reportRuntimeError);
  }, [enableSplit, reportRuntimeError]);
  const splitDown = useCallback(() => {
    void enableSplit("vertical").catch(reportRuntimeError);
  }, [enableSplit, reportRuntimeError]);

  const handleSelectWorktreeByIndex = useCallback(
    (index: number) => {
      const target = state.worktrees[index];
      if (target) {
        handleSelectWorktree(target);
      }
    },
    [handleSelectWorktree, state.worktrees],
  );

  const handleSelectTerminalTabByIndex = useCallback(
    (index: number) => {
      const target = state.layout.tabs[index];
      if (target) {
        handleSelectTerminalTab(target.id);
      }
    },
    [handleSelectTerminalTab, state.layout.tabs],
  );

  const shortcutHandlers = useMemo(
    () => ({
      "tab.newTerminal": handleAddTerminalTab,
      "tab.close": () => {
        if (state.layout.primaryTabId) handleCloseTab(state.layout.primaryTabId);
      },
      "tab.next": () => handleCycleTab(1),
      "tab.previous": () => handleCycleTab(-1),
      "tab.select1": () => handleSelectTerminalTabByIndex(0),
      "tab.select2": () => handleSelectTerminalTabByIndex(1),
      "tab.select3": () => handleSelectTerminalTabByIndex(2),
      "tab.select4": () => handleSelectTerminalTabByIndex(3),
      "workspace.select1": () => handleSelectWorktreeByIndex(0),
      "workspace.select2": () => handleSelectWorktreeByIndex(1),
      "workspace.select3": () => handleSelectWorktreeByIndex(2),
      "workspace.select4": () => handleSelectWorktreeByIndex(3),
      "terminal.splitRight": splitRight,
      "terminal.splitDown": splitDown,
      "terminal.unsplit": disableSplit,
      "sidebar.left.toggle": toggleSidebar,
      "commandPalette.open": () => setIsCommandPaletteOpen(true),
    }),
    [
      disableSplit,
      handleAddTerminalTab,
      handleCloseTab,
      handleCycleTab,
      handleSelectTerminalTabByIndex,
      handleSelectWorktreeByIndex,
      splitDown,
      splitRight,
      state.layout.primaryTabId,
      toggleSidebar,
    ],
  );
  useShortcuts(shortcutHandlers);

  return (
    <div className="flex h-screen w-screen select-none overflow-hidden bg-background font-sans text-foreground">
      <Sidebar
        open={isSidebarOpen}
        projects={projects}
        activeProjectId={activeProject.workspaceId}
        worktrees={state.worktrees}
        agents={agents}
        activePath={activeWorktree?.path || ""}
        statuses={worktreeStatuses}
        onSelectProject={handleSelectProject}
        onAddProject={() => setIsAddProjectOpen(true)}
        onSelectWorktree={handleSelectWorktree}
        onCreateWorktree={() => setIsCreateOpen(true)}
        onRefreshWorktreeStatus={handleRefreshWorktreeStatus}
        onDeleteWorktree={setDeleteTarget}
        onOpenCommandPalette={() => setIsCommandPaletteOpen(true)}
        onOpenSettings={() => setIsSettingsOpen(true)}
        onToggle={toggleSidebar}
      />

      <main className="flex h-full min-w-0 flex-1 flex-col overflow-hidden bg-background">
        {activeWorktree ? (
          <TerminalSplitView
            layout={state.layout}
            sessions={state.sessions}
            onActivateTab={handleSelectTerminalTab}
            onCloseTab={handleCloseTab}
            onAddTab={handleAddTerminalTab}
            onSplitRight={splitRight}
            onSplitDown={splitDown}
            onUnsplit={disableSplit}
            onTitleChange={updateTabTitle}
          />
        ) : (
          <div className="flex h-full flex-1 items-center justify-center bg-[#23262d] text-xs text-muted-foreground">
            {runtimeError ? `Workspace unavailable (${runtimeError.code})` : "No workspace available"}
          </div>
        )}
      </main>

      <CommandPalette
        open={isCommandPaletteOpen}
        worktrees={state.worktrees}
        tabs={state.layout.tabs}
        onSelectWorktree={handleSelectWorktree}
        onSelectTab={handleSelectTerminalTab}
        onClose={() => setIsCommandPaletteOpen(false)}
      />
      <SettingsDialog open={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} />
      {isAddProjectOpen ? (
        <AddProjectDialog onClose={() => setIsAddProjectOpen(false)} onRegistered={handleRegisteredProject} />
      ) : null}
      {isCreateOpen ? (
        <AddWorktreeDialog
          project={activeProject}
          onClose={() => setIsCreateOpen(false)}
          onCreated={async (worktree) => {
            await refreshWorktrees();
            await ensureTabForWorktree(worktree).catch(reportRuntimeError);
          }}
        />
      ) : null}
      {deleteTarget ? (
        <WorktreeDeleteDialog
          workspaceId={activeProject.workspaceId}
          worktree={deleteTarget}
          onClose={() => setDeleteTarget(null)}
          onDeleted={() => {
            setWorktreeStatuses((current) => {
              const next = { ...current };
              delete next[deleteTarget.path];
              return next;
            });
            void refreshWorktrees();
          }}
        />
      ) : null}

      {runtimeError && activeWorktree ? (
        <div className="pointer-events-none fixed bottom-3 right-3 z-40 max-w-error border border-destructive/30 bg-card/95 px-3 py-2 text-[11px] text-destructive shadow-lg">
          {runtimeError.code}: {runtimeError.message}
        </div>
      ) : null}
    </div>
  );
}

function loadProjects(): RegisteredProject[] {
  try {
    const raw = window.localStorage.getItem(PROJECTS_STORAGE_KEY);
    if (!raw) return [DEFAULT_PROJECT];
    const parsed = JSON.parse(raw) as RegisteredProject[];
    if (!Array.isArray(parsed)) return [DEFAULT_PROJECT];
    const valid = parsed.filter(
      (project) => project && typeof project.workspaceId === "string" && typeof project.repoRoot === "string",
    );
    return valid.length > 0 ? valid : [DEFAULT_PROJECT];
  } catch {
    return [DEFAULT_PROJECT];
  }
}

function persistProjects(projects: RegisteredProject[]) {
  try {
    window.localStorage.setItem(PROJECTS_STORAGE_KEY, JSON.stringify(projects));
  } catch {
    // A local persistence failure must not block native project registration.
  }
}

function loadActiveProjectId() {
  try {
    return window.localStorage.getItem(ACTIVE_PROJECT_STORAGE_KEY) || DEFAULT_WORKSPACE_ID;
  } catch {
    return DEFAULT_WORKSPACE_ID;
  }
}

function persistActiveProjectId(workspaceId: string) {
  try {
    window.localStorage.setItem(ACTIVE_PROJECT_STORAGE_KEY, workspaceId);
  } catch {
    // The selected project still remains active for this session.
  }
}

function loadSidebarOpen() {
  try {
    const raw = window.localStorage.getItem(SIDEBAR_OPEN_STORAGE_KEY);
    return raw !== null ? raw !== "false" : true;
  } catch {
    return true;
  }
}

function persistSidebarOpen(open: boolean) {
  try {
    window.localStorage.setItem(SIDEBAR_OPEN_STORAGE_KEY, String(open));
  } catch {
    // Persistence failure should not break in-memory state.
  }
}

