import type { LayoutState, TabPaneLayout, TerminalTab } from "../lib/types";
import {
  collectLeafIds,
  createLeafNode,
  findFirstLeafId,
  findSiblingLeafId,
  removeLeaf,
  setRatioAtPath,
  splitLeaf,
  swapLeaves,
  type PaneDirection,
  type PaneNode,
} from "./paneTree";

export type LayoutAction =
  | { type: "ADD_TAB"; tab: TerminalTab; sessionId?: string; leafId?: string; activate?: boolean }
  | { type: "RENAME_TAB"; tabId: string; label: string }
  | { type: "CLOSE_TAB"; tabId: string; replacementTab?: TerminalTab; replacementSessionId?: string }
  | { type: "ACTIVATE_TAB"; tabId: string }
  | {
      type: "SPLIT_PANE";
      tabId: string;
      targetLeafId: string;
      direction: PaneDirection;
      newLeafId: string;
      sessionId: string;
      position?: "first" | "second";
    }
  | { type: "CLOSE_PANE"; tabId: string; leafId: string }
  | { type: "FOCUS_PANE"; tabId: string; leafId: string }
  | { type: "SET_PANE_RATIO"; tabId: string; path: string; ratio: number }
  | { type: "SWAP_PANES"; tabId: string; sourceLeafId: string; targetLeafId: string }
  | { type: "TOGGLE_PANE_EXPANSION"; tabId: string; leafId: string };

export function createLayoutState(tabs: TerminalTab[] = [], activeTabId?: string | null): LayoutState {
  const layoutsByTabId: Record<string, TabPaneLayout> = {};
  for (const tab of dedupeTabs(tabs)) {
    layoutsByTabId[tab.id] = createTabLayout(tab.sessionId);
  }
  return normalizeLayout({
    tabs,
    activeTabId: activeTabId ?? tabs[0]?.id ?? null,
    layoutsByTabId,
  });
}

/** Builds a single-pane layout for a freshly opened tab. */
export function createTabLayout(sessionId: string, leafId?: string): TabPaneLayout {
  const root = createLeafNode(leafId);
  const rootLeafId = findFirstLeafId(root);
  return {
    root,
    activeLeafId: rootLeafId,
    expandedLeafId: null,
    sessionIdsByLeafId: { [rootLeafId]: sessionId },
  };
}

export function layoutReducer(state: LayoutState, action: LayoutAction): LayoutState {
  switch (action.type) {
    case "ADD_TAB": {
      const exists = state.tabs.some((tab) => tab.id === action.tab.id);
      const tabs = exists ? state.tabs : [...state.tabs, action.tab];
      const layoutsByTabId = exists
        ? state.layoutsByTabId
        : {
            ...state.layoutsByTabId,
            [action.tab.id]: createTabLayout(action.sessionId ?? action.tab.sessionId, action.leafId),
          };
      return normalizeLayout({
        tabs,
        layoutsByTabId,
        activeTabId: action.activate === false ? state.activeTabId : action.tab.id,
      });
    }
    case "RENAME_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      const tabs = state.tabs.map((tab) => (tab.id === action.tabId ? { ...tab, label: action.label } : tab));
      return { ...state, tabs };
    }
    case "CLOSE_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return normalizeLayout(state);

      const layoutsByTabId = { ...state.layoutsByTabId };
      delete layoutsByTabId[action.tabId];

      let tabs = state.tabs.filter((tab) => tab.id !== action.tabId);
      let activeTabId = state.activeTabId === action.tabId ? nextActiveTabId(state, action.tabId) : state.activeTabId;

      if (tabs.length === 0 && action.replacementTab) {
        tabs = [action.replacementTab];
        layoutsByTabId[action.replacementTab.id] = createTabLayout(
          action.replacementSessionId ?? action.replacementTab.sessionId,
        );
        activeTabId = action.replacementTab.id;
      }

      return normalizeLayout({ tabs, activeTabId, layoutsByTabId });
    }
    case "ACTIVATE_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayout({ ...state, activeTabId: action.tabId });
    }
    case "SPLIT_PANE": {
      const layout = state.layoutsByTabId[action.tabId];
      if (!layout || !layout.sessionIdsByLeafId[action.targetLeafId]) return state;
      if (layout.sessionIdsByLeafId[action.newLeafId]) return state;

      const root = splitLeaf(
        layout.root,
        action.targetLeafId,
        action.newLeafId,
        action.direction,
        action.position ?? "second",
      );
      if (root === layout.root) return state;

      return replaceTabLayout(state, action.tabId, {
        ...layout,
        root,
        activeLeafId: action.newLeafId,
        // A new pane must be visible, so any zoomed pane is restored.
        expandedLeafId: null,
        sessionIdsByLeafId: { ...layout.sessionIdsByLeafId, [action.newLeafId]: action.sessionId },
      });
    }
    case "CLOSE_PANE": {
      const layout = state.layoutsByTabId[action.tabId];
      if (!layout || !layout.sessionIdsByLeafId[action.leafId]) return state;

      // Closing the sole pane of a tab closes the tab itself.
      const root = removeLeaf(layout.root, action.leafId);
      if (root === null) return layoutReducer(state, { type: "CLOSE_TAB", tabId: action.tabId });

      const fallbackLeafId = findSiblingLeafId(layout.root, action.leafId) ?? findFirstLeafId(root);
      const sessionIdsByLeafId = { ...layout.sessionIdsByLeafId };
      delete sessionIdsByLeafId[action.leafId];

      return replaceTabLayout(state, action.tabId, {
        ...layout,
        root,
        activeLeafId: layout.activeLeafId === action.leafId ? fallbackLeafId : layout.activeLeafId,
        expandedLeafId: layout.expandedLeafId === action.leafId ? null : layout.expandedLeafId,
        sessionIdsByLeafId,
      });
    }
    case "FOCUS_PANE": {
      const layout = state.layoutsByTabId[action.tabId];
      if (!layout || !layout.sessionIdsByLeafId[action.leafId]) return state;
      if (layout.activeLeafId === action.leafId) return state;
      return replaceTabLayout(state, action.tabId, { ...layout, activeLeafId: action.leafId });
    }
    case "SET_PANE_RATIO": {
      const layout = state.layoutsByTabId[action.tabId];
      if (!layout) return state;
      const root = setRatioAtPath(layout.root, action.path, action.ratio);
      if (root === layout.root) return state;
      return replaceTabLayout(state, action.tabId, { ...layout, root });
    }
    case "SWAP_PANES": {
      const layout = state.layoutsByTabId[action.tabId];
      if (!layout) return state;
      const root = swapLeaves(layout.root, action.sourceLeafId, action.targetLeafId);
      if (root === layout.root) return state;
      return replaceTabLayout(state, action.tabId, { ...layout, root });
    }
    case "TOGGLE_PANE_EXPANSION": {
      const layout = state.layoutsByTabId[action.tabId];
      if (!layout || !layout.sessionIdsByLeafId[action.leafId]) return state;
      const expandedLeafId = layout.expandedLeafId === action.leafId ? null : action.leafId;
      return replaceTabLayout(state, action.tabId, { ...layout, expandedLeafId, activeLeafId: action.leafId });
    }
  }
}

/** Every session id rendered by the tab, in tree order. */
export function selectTabSessionIds(layout: LayoutState, tabId: string): string[] {
  const tabLayout = layout.layoutsByTabId[tabId];
  if (!tabLayout) return [];
  return collectLeafIds(tabLayout.root)
    .map((leafId) => tabLayout.sessionIdsByLeafId[leafId])
    .filter((sessionId): sessionId is string => Boolean(sessionId));
}

/** Every session id still referenced by any tab, used to decide which backends stay alive. */
export function selectLiveSessionIds(layout: LayoutState): Set<string> {
  const live = new Set<string>();
  for (const tab of layout.tabs) {
    for (const sessionId of selectTabSessionIds(layout, tab.id)) live.add(sessionId);
  }
  return live;
}

function replaceTabLayout(state: LayoutState, tabId: string, tabLayout: TabPaneLayout): LayoutState {
  return { ...state, layoutsByTabId: { ...state.layoutsByTabId, [tabId]: tabLayout } };
}

function nextActiveTabId(state: LayoutState, closingTabId: string): string | null {
  const index = state.tabs.findIndex((tab) => tab.id === closingTabId);
  const remaining = state.tabs.filter((tab) => tab.id !== closingTabId);
  if (remaining.length === 0) return null;
  return remaining[Math.min(Math.max(index, 0), remaining.length - 1)].id;
}

function normalizeLayout(state: LayoutState): LayoutState {
  const tabs = dedupeTabs(state.tabs);

  const layoutsByTabId: Record<string, TabPaneLayout> = {};
  for (const tab of tabs) {
    layoutsByTabId[tab.id] = normalizeTabLayout(state.layoutsByTabId[tab.id], tab.sessionId);
  }

  const activeTabId = tabs.some((tab) => tab.id === state.activeTabId) ? state.activeTabId : tabs[0]?.id ?? null;

  return { tabs, activeTabId, layoutsByTabId };
}

/** Guarantees a tab always has a tree whose leaves all map to a session. */
function normalizeTabLayout(layout: TabPaneLayout | undefined, fallbackSessionId: string): TabPaneLayout {
  if (!layout) return createTabLayout(fallbackSessionId);

  const leafIds = collectLeafIds(layout.root);
  const sessionIdsByLeafId: Record<string, string> = {};
  for (const leafId of leafIds) {
    sessionIdsByLeafId[leafId] = layout.sessionIdsByLeafId[leafId] ?? fallbackSessionId;
  }

  const activeLeafId =
    layout.activeLeafId && leafIds.includes(layout.activeLeafId) ? layout.activeLeafId : leafIds[0] ?? null;
  const expandedLeafId =
    layout.expandedLeafId && leafIds.includes(layout.expandedLeafId) ? layout.expandedLeafId : null;

  if (
    activeLeafId === layout.activeLeafId &&
    expandedLeafId === layout.expandedLeafId &&
    sameSessionMap(layout.sessionIdsByLeafId, sessionIdsByLeafId)
  ) {
    return layout;
  }

  return { root: layout.root, activeLeafId, expandedLeafId, sessionIdsByLeafId };
}

function sameSessionMap(left: Record<string, string>, right: Record<string, string>) {
  const leftKeys = Object.keys(left);
  if (leftKeys.length !== Object.keys(right).length) return false;
  return leftKeys.every((key) => left[key] === right[key]);
}

function dedupeTabs(tabs: TerminalTab[]) {
  const seen = new Set<string>();
  return tabs.filter((tab) => {
    if (seen.has(tab.id)) return false;
    seen.add(tab.id);
    return true;
  });
}

export type { PaneDirection, PaneNode };

