import { describe, expect, it } from "vitest";

import type { TerminalTab } from "../lib/types";
import { createLayoutState, createTabLayout, layoutReducer, selectLiveSessionIds, selectTabSessionIds } from "./layout";
import { collectLeafIds, MAX_PANE_RATIO, MIN_PANE_RATIO, type PaneNode } from "./paneTree";

function tab(id: string, sessionId: string): TerminalTab {
  return { id, label: id, sessionId };
}

/** A layout with one tab whose single pane is a leaf with a known id. */
function singleTabState(tabId = "tab-1", sessionId = "session-1", leafId = "pane-1") {
  const terminalTab = tab(tabId, sessionId);
  const state = layoutReducer(createLayoutState(), {
    type: "ADD_TAB",
    tab: terminalTab,
    sessionId,
    leafId,
  });
  return { state, tab: terminalTab };
}

function rootOf(state: ReturnType<typeof layoutReducer>, tabId: string): PaneNode {
  return state.layoutsByTabId[tabId].root;
}

describe("createLayoutState", () => {
  it("gives every seeded tab an independent single-leaf tree bound to its session", () => {
    const first = tab("tab-1", "session-1");
    const second = tab("tab-2", "session-2");

    const state = createLayoutState([first, second], second.id);

    expect(state.tabs).toEqual([first, second]);
    expect(state.activeTabId).toBe(second.id);
    expect(Object.keys(state.layoutsByTabId)).toEqual([first.id, second.id]);

    for (const seeded of [first, second]) {
      const layout = state.layoutsByTabId[seeded.id];
      expect(layout.root.type).toBe("leaf");
      expect(layout.expandedLeafId).toBeNull();
      expect(selectTabSessionIds(state, seeded.id)).toEqual([seeded.sessionId]);
      expect(layout.activeLeafId).toBe(collectLeafIds(layout.root)[0]);
    }
  });

  it("falls back to the first tab when the requested active tab does not exist", () => {
    const state = createLayoutState([tab("tab-1", "session-1")], "missing");
    expect(state.activeTabId).toBe("tab-1");
  });

  it("starts empty with no active tab and no layouts", () => {
    expect(createLayoutState()).toEqual({ tabs: [], activeTabId: null, layoutsByTabId: {} });
  });
});

describe("ADD_TAB", () => {
  it("creates a tab with a single leaf pane mapped to its session", () => {
    const { state, tab: added } = singleTabState();

    expect(state.tabs).toEqual([added]);
    expect(state.activeTabId).toBe(added.id);
    expect(state.layoutsByTabId[added.id]).toEqual({
      root: { type: "leaf", leafId: "pane-1" },
      activeLeafId: "pane-1",
      expandedLeafId: null,
      sessionIdsByLeafId: { "pane-1": "session-1" },
    });
  });

  it("adds a tab without activating it when activate is false", () => {
    const { state, tab: first } = singleTabState();

    const next = layoutReducer(state, {
      type: "ADD_TAB",
      tab: tab("tab-2", "session-2"),
      activate: false,
    });

    expect(next.tabs.map((candidate) => candidate.id)).toEqual(["tab-1", "tab-2"]);
    expect(next.activeTabId).toBe(first.id);
    expect(selectTabSessionIds(next, "tab-2")).toEqual(["session-2"]);
  });

  it("keeps the existing tree when the same tab id is added twice", () => {
    const { state, tab: first } = singleTabState();
    const split = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: first.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    const next = layoutReducer(split, { type: "ADD_TAB", tab: first, sessionId: "session-1" });

    expect(next.tabs).toHaveLength(1);
    expect(next.layoutsByTabId[first.id]).toBe(split.layoutsByTabId[first.id]);
  });
});

describe("SPLIT_PANE", () => {
  it("splits the only pane horizontally and focuses the new leaf", () => {
    const { state, tab: only } = singleTabState();

    const next = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    expect(rootOf(next, only.id)).toEqual({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "pane-1" },
      second: { type: "leaf", leafId: "pane-2" },
      ratio: 0.5,
    });
    expect(next.layoutsByTabId[only.id].activeLeafId).toBe("pane-2");
    expect(selectTabSessionIds(next, only.id)).toEqual(["session-1", "session-2"]);
  });

  it("splits vertically and honours a first-position placement", () => {
    const { state, tab: only } = singleTabState();

    const next = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "vertical",
      newLeafId: "pane-2",
      sessionId: "session-2",
      position: "first",
    });

    expect(rootOf(next, only.id)).toMatchObject({
      type: "split",
      direction: "vertical",
      first: { type: "leaf", leafId: "pane-2" },
      second: { type: "leaf", leafId: "pane-1" },
    });
  });

  it("splits any target pane, not just the active one", () => {
    const { state, tab: only } = singleTabState();
    const twoPanes = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    // pane-2 is active, but pane-1 is the split target.
    const next = layoutReducer(twoPanes, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "vertical",
      newLeafId: "pane-3",
      sessionId: "session-3",
    });

    expect(rootOf(next, only.id)).toEqual({
      type: "split",
      direction: "horizontal",
      first: {
        type: "split",
        direction: "vertical",
        first: { type: "leaf", leafId: "pane-1" },
        second: { type: "leaf", leafId: "pane-3" },
        ratio: 0.5,
      },
      second: { type: "leaf", leafId: "pane-2" },
      ratio: 0.5,
    });
    expect(selectTabSessionIds(next, only.id)).toEqual(["session-1", "session-3", "session-2"]);
  });

  it("splits one tab without touching the tree of any other tab", () => {
    const { state } = singleTabState();
    const twoTabs = layoutReducer(state, {
      type: "ADD_TAB",
      tab: tab("tab-2", "session-2"),
      sessionId: "session-2",
      leafId: "pane-2",
    });

    const next = layoutReducer(twoTabs, {
      type: "SPLIT_PANE",
      tabId: "tab-2",
      targetLeafId: "pane-2",
      direction: "horizontal",
      newLeafId: "pane-3",
      sessionId: "session-3",
    });

    expect(next.layoutsByTabId["tab-1"]).toBe(twoTabs.layoutsByTabId["tab-1"]);
    expect(rootOf(next, "tab-1").type).toBe("leaf");
    expect(rootOf(next, "tab-2").type).toBe("split");
  });

  it("restores an expanded pane so the new pane is visible", () => {
    const { state, tab: only } = singleTabState();
    const expanded = layoutReducer(state, { type: "TOGGLE_PANE_EXPANSION", tabId: only.id, leafId: "pane-1" });
    expect(expanded.layoutsByTabId[only.id].expandedLeafId).toBe("pane-1");

    const next = layoutReducer(expanded, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    expect(next.layoutsByTabId[only.id].expandedLeafId).toBeNull();
  });

  it("ignores splits of unknown tabs, unknown targets, and duplicate leaf ids", () => {
    const { state, tab: only } = singleTabState();
    const base = {
      type: "SPLIT_PANE",
      direction: "horizontal",
      sessionId: "session-2",
    } as const;

    expect(layoutReducer(state, { ...base, tabId: "missing", targetLeafId: "pane-1", newLeafId: "pane-2" })).toBe(state);
    expect(layoutReducer(state, { ...base, tabId: only.id, targetLeafId: "missing", newLeafId: "pane-2" })).toBe(state);
    expect(layoutReducer(state, { ...base, tabId: only.id, targetLeafId: "pane-1", newLeafId: "pane-1" })).toBe(state);
  });
});

describe("CLOSE_PANE", () => {
  it("collapses the parent split into the surviving sibling and drops its session", () => {
    const { state, tab: only } = singleTabState();
    const split = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    const next = layoutReducer(split, { type: "CLOSE_PANE", tabId: only.id, leafId: "pane-2" });

    expect(rootOf(next, only.id)).toEqual({ type: "leaf", leafId: "pane-1" });
    expect(next.layoutsByTabId[only.id].sessionIdsByLeafId).toEqual({ "pane-1": "session-1" });
    expect(next.tabs).toHaveLength(1);
  });

  it("moves focus to the sibling pane when the focused pane closes", () => {
    const { state, tab: only } = singleTabState();
    const split = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });
    expect(split.layoutsByTabId[only.id].activeLeafId).toBe("pane-2");

    const next = layoutReducer(split, { type: "CLOSE_PANE", tabId: only.id, leafId: "pane-2" });

    expect(next.layoutsByTabId[only.id].activeLeafId).toBe("pane-1");
  });

  it("keeps focus untouched when a different pane closes", () => {
    const { state, tab: only } = singleTabState();
    const threePanes = [
      { targetLeafId: "pane-1", newLeafId: "pane-2", sessionId: "session-2" },
      { targetLeafId: "pane-2", newLeafId: "pane-3", sessionId: "session-3" },
    ].reduce(
      (current, step) =>
        layoutReducer(current, { type: "SPLIT_PANE", tabId: only.id, direction: "horizontal", ...step }),
      state,
    );
    const focused = layoutReducer(threePanes, { type: "FOCUS_PANE", tabId: only.id, leafId: "pane-1" });

    const next = layoutReducer(focused, { type: "CLOSE_PANE", tabId: only.id, leafId: "pane-3" });

    expect(next.layoutsByTabId[only.id].activeLeafId).toBe("pane-1");
    expect(collectLeafIds(rootOf(next, only.id))).toEqual(["pane-1", "pane-2"]);
  });

  it("closes the tab when its last pane closes", () => {
    const { state, tab: only } = singleTabState();
    const twoTabs = layoutReducer(state, {
      type: "ADD_TAB",
      tab: tab("tab-2", "session-2"),
      sessionId: "session-2",
      leafId: "pane-2",
    });

    const next = layoutReducer(twoTabs, { type: "CLOSE_PANE", tabId: only.id, leafId: "pane-1" });

    expect(next.tabs.map((candidate) => candidate.id)).toEqual(["tab-2"]);
    expect(next.layoutsByTabId[only.id]).toBeUndefined();
    expect(next.activeTabId).toBe("tab-2");
  });

  it("ignores unknown tabs and unknown leaves", () => {
    const { state, tab: only } = singleTabState();

    expect(layoutReducer(state, { type: "CLOSE_PANE", tabId: "missing", leafId: "pane-1" })).toBe(state);
    expect(layoutReducer(state, { type: "CLOSE_PANE", tabId: only.id, leafId: "missing" })).toBe(state);
  });
});

describe("FOCUS_PANE", () => {
  it("updates only the target tab's active leaf", () => {
    const { state, tab: only } = singleTabState();
    const split = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    const next = layoutReducer(split, { type: "FOCUS_PANE", tabId: only.id, leafId: "pane-1" });

    expect(next.layoutsByTabId[only.id].activeLeafId).toBe("pane-1");
    expect(rootOf(next, only.id)).toBe(rootOf(split, only.id));
  });

  it("ignores focus for unknown leaves and no-op refocus", () => {
    const { state, tab: only } = singleTabState();

    expect(layoutReducer(state, { type: "FOCUS_PANE", tabId: only.id, leafId: "missing" })).toBe(state);
    expect(layoutReducer(state, { type: "FOCUS_PANE", tabId: only.id, leafId: "pane-1" })).toBe(state);
