describe("SET_PANE_RATIO", () => {
  it("sets the root split ratio for one tab only", () => {
    const { state, tab: only } = singleTabState();
    const split = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    const next = layoutReducer(split, { type: "SET_PANE_RATIO", tabId: only.id, path: "", ratio: 0.7 });

    expect(rootOf(next, only.id)).toMatchObject({ type: "split", ratio: 0.7 });
  });

  it("sets a nested split ratio addressed by path", () => {
    const { state, tab: only } = singleTabState();
    const nested = [
      { targetLeafId: "pane-1", newLeafId: "pane-2", direction: "horizontal" as const, sessionId: "session-2" },
      { targetLeafId: "pane-2", newLeafId: "pane-3", direction: "vertical" as const, sessionId: "session-3" },
    ].reduce((current, step) => layoutReducer(current, { type: "SPLIT_PANE", tabId: only.id, ...step }), state);

    const next = layoutReducer(nested, { type: "SET_PANE_RATIO", tabId: only.id, path: "second", ratio: 0.25 });

    expect(rootOf(next, only.id)).toMatchObject({
      ratio: 0.5,
      second: { type: "split", direction: "vertical", ratio: 0.25 },
    });
  });

  it("clamps out-of-range ratios into the usable pane range", () => {
    const { state, tab: only } = singleTabState();
    const split = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    const tooSmall = layoutReducer(split, { type: "SET_PANE_RATIO", tabId: only.id, path: "", ratio: -3 });
    const tooLarge = layoutReducer(split, { type: "SET_PANE_RATIO", tabId: only.id, path: "", ratio: 42 });

    expect(tooSmall.layoutsByTabId[only.id].root).toMatchObject({ ratio: MIN_PANE_RATIO });
    expect(tooLarge.layoutsByTabId[only.id].root).toMatchObject({ ratio: MAX_PANE_RATIO });
  });

  it("ignores ratio changes for unknown tabs and for single-pane tabs", () => {
    const { state, tab: only } = singleTabState();

    expect(layoutReducer(state, { type: "SET_PANE_RATIO", tabId: "missing", path: "", ratio: 0.7 })).toBe(state);
    expect(layoutReducer(state, { type: "SET_PANE_RATIO", tabId: only.id, path: "", ratio: 0.7 })).toBe(state);
  });
});

describe("SWAP_PANES", () => {
  it("swaps two pane positions for drag-to-reorder while keeping their sessions", () => {
    const { state, tab: only } = singleTabState();
    const split = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    const next = layoutReducer(split, {
      type: "SWAP_PANES",
      tabId: only.id,
      sourceLeafId: "pane-1",
      targetLeafId: "pane-2",
    });

    expect(collectLeafIds(rootOf(next, only.id))).toEqual(["pane-2", "pane-1"]);
    expect(next.layoutsByTabId[only.id].sessionIdsByLeafId).toEqual({
      "pane-1": "session-1",
      "pane-2": "session-2",
    });
    expect(selectTabSessionIds(next, only.id)).toEqual(["session-2", "session-1"]);
  });

  it("ignores swaps of unknown or identical panes", () => {
    const { state, tab: only } = singleTabState();
    const split = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: only.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-2",
      sessionId: "session-2",
    });

    expect(
      layoutReducer(split, { type: "SWAP_PANES", tabId: only.id, sourceLeafId: "pane-1", targetLeafId: "pane-1" }),
    ).toBe(split);
    expect(
      layoutReducer(split, { type: "SWAP_PANES", tabId: only.id, sourceLeafId: "pane-1", targetLeafId: "missing" }),
    ).toBe(split);
    expect(
      layoutReducer(split, { type: "SWAP_PANES", tabId: "missing", sourceLeafId: "pane-1", targetLeafId: "pane-2" }),
    ).toBe(split);
  });
});

describe("CLOSE_TAB", () => {
  it("removes the tab together with its whole pane layout", () => {
    const { state, tab: first } = singleTabState();
    const twoTabs = layoutReducer(state, {
      type: "ADD_TAB",
      tab: tab("tab-2", "session-2"),
      sessionId: "session-2",
      leafId: "pane-2",
    });
    const splitFirst = layoutReducer(twoTabs, {
      type: "SPLIT_PANE",
      tabId: first.id,
      targetLeafId: "pane-1",
      direction: "horizontal",
      newLeafId: "pane-3",
      sessionId: "session-3",
    });

    const next = layoutReducer(splitFirst, { type: "CLOSE_TAB", tabId: first.id });

    expect(next.tabs.map((candidate) => candidate.id)).toEqual(["tab-2"]);
    expect(next.layoutsByTabId).not.toHaveProperty(first.id);
    expect(selectLiveSessionIds(next)).toEqual(new Set(["session-2"]));
  });

  it("applies the last-tab-close replacement policy atomically", () => {
    const { state, tab: only } = singleTabState();
    const replacement = tab("tab-2", "session-2");

    const next = layoutReducer(state, {
      type: "CLOSE_TAB",
      tabId: only.id,
      replacementTab: replacement,
      replacementSessionId: replacement.sessionId,
    });

    expect(next.tabs).toEqual([replacement]);
    expect(next.activeTabId).toBe(replacement.id);
    expect(next.layoutsByTabId).not.toHaveProperty(only.id);
    expect(selectTabSessionIds(next, replacement.id)).toEqual(["session-2"]);
    expect(next.layoutsByTabId[replacement.id].root.type).toBe("leaf");
  });

  it("activates the neighbouring tab when the active tab closes", () => {
    const seeded = createLayoutState([tab("tab-1", "s1"), tab("tab-2", "s2"), tab("tab-3", "s3")], "tab-2");

    const next = layoutReducer(seeded, { type: "CLOSE_TAB", tabId: "tab-2" });

    expect(next.tabs.map((candidate) => candidate.id)).toEqual(["tab-1", "tab-3"]);
    expect(next.activeTabId).toBe("tab-3");
  });

  it("empties the layout when the only tab closes without a replacement", () => {
    const { state, tab: only } = singleTabState();

    const next = layoutReducer(state, { type: "CLOSE_TAB", tabId: only.id });

    expect(next).toEqual({ tabs: [], activeTabId: null, layoutsByTabId: {} });
  });
});

describe("ACTIVATE_TAB and RENAME_TAB", () => {
  it("activates an existing tab and ignores unknown ids", () => {
    const seeded = createLayoutState([tab("tab-1", "s1"), tab("tab-2", "s2")], "tab-1");

    expect(layoutReducer(seeded, { type: "ACTIVATE_TAB", tabId: "tab-2" }).activeTabId).toBe("tab-2");
    expect(layoutReducer(seeded, { type: "ACTIVATE_TAB", tabId: "missing" })).toBe(seeded);
  });

  it("renames a tab without touching other tabs or any pane tree", () => {
    const seeded = createLayoutState([tab("tab-1", "s1"), tab("tab-2", "s2")], "tab-1");

    const renamed = layoutReducer(seeded, { type: "RENAME_TAB", tabId: "tab-1", label: "omo: build" });

    expect(renamed.tabs[0].label).toBe("omo: build");
    expect(renamed.tabs[1].label).toBe("tab-2");
    expect(renamed.activeTabId).toBe("tab-1");
    expect(renamed.layoutsByTabId).toBe(seeded.layoutsByTabId);
  });
});

describe("selectors", () => {
  it("lists tab session ids in tree order and dedupes live sessions across tabs", () => {
    const { state, tab: first } = singleTabState();
    const shared = layoutReducer(state, {
      type: "ADD_TAB",
      tab: tab("tab-2", "session-1"),
      sessionId: "session-1",
      leafId: "pane-2",
    });
    const split = layoutReducer(shared, {
      type: "SPLIT_PANE",
      tabId: first.id,
      targetLeafId: "pane-1",
      direction: "vertical",
      newLeafId: "pane-3",
      sessionId: "session-3",
      position: "first",
    });

    expect(selectTabSessionIds(split, first.id)).toEqual(["session-3", "session-1"]);
    expect(selectLiveSessionIds(split)).toEqual(new Set(["session-1", "session-3"]));
    expect(selectTabSessionIds(split, "missing")).toEqual([]);
  });
});

describe("createTabLayout", () => {
  it("builds a focused single-pane layout bound to the given session", () => {
    expect(createTabLayout("session-9", "pane-9")).toEqual({
      root: { type: "leaf", leafId: "pane-9" },
      activeLeafId: "pane-9",
      expandedLeafId: null,
      sessionIdsByLeafId: { "pane-9": "session-9" },
    });
  });
});

