it("drops a closed tab's whole pane tree and every PTY it alone owned", async () => {
  const { services } = createServices();
  const { result } = renderHook(() =>
    useWorkspaceStore({ initialWorktrees: [worktree, featureWorktree], services }),
  );

  await act(async () => {
    await result.current.openTab(worktree);
    await result.current.openTab(featureWorktree);
  });
  const [survivingTab, closingTab] = result.current.state.layout.tabs;
  const closingSessionIds = Object.values(tabPanes(result.current.state, closingTab.id).layout.sessionIdsByLeafId);
  const closingBackendIds = closingSessionIds.map(
    (sessionId) => result.current.state.sessions[sessionId].backendSessionId,
  );

  await act(async () => {
    await result.current.closeTab(closingTab.id);
  });

  expect(result.current.state.layout.tabs.map((tab) => tab.id)).toEqual([survivingTab.id]);
  expect(result.current.state.layout.activeTabId).toBe(survivingTab.id);
  expect(result.current.state.layout.layoutsByTabId[closingTab.id]).toBeUndefined();
  for (const backendId of closingBackendIds) {
    expect(services.closeTerminal).toHaveBeenCalledWith(backendId);
  }
  for (const sessionId of closingSessionIds) {
    expect(result.current.state.sessions[sessionId]).toBeUndefined();
  }
});

