/**
 * Splits a pane of the active tab.
 *
 * A worktree holds exactly one writer lease, so splitting inside the same worktree mirrors
 * the source pane's session instead of spawning a second PTY that the backend would reject.
 * Passing an explicit `worktree` for a different directory spawns a PTY of its own.
 */
const splitPane = useCallback(
  async (
    direction: PaneDirection = "horizontal",
    options: { tabId?: string; targetLeafId?: string; worktree?: Worktree } = {},
  ) => {
    let snapshot = stateRef.current;
    let tabId = options.tabId ?? snapshot.layout.activeTabId;

    if (!tabId) {
      const activeWorktree = options.worktree ?? getActiveWorktree(snapshot);
      if (!activeWorktree) return;
      tabId = await openTab(activeWorktree);
      snapshot = stateRef.current;
    }

    const tabLayout = snapshot.layout.layoutsByTabId[tabId];
    if (!tabLayout) return;
    const targetLeafId = options.targetLeafId ?? tabLayout.activeLeafId;
    if (!targetLeafId) return;

    const sourceSessionId = tabLayout.sessionIdsByLeafId[targetLeafId];
    const sourceSession = sourceSessionId ? snapshot.sessions[sourceSessionId] : undefined;
    const targetWorktree = options.worktree ?? null;

    const reusableSession =
      !targetWorktree || targetWorktree.path === sourceSession?.cwd
        ? sourceSession
