it("splits the active tab into a pane tree with its own backend PTY", async () => {
  const { services } = createServices();
  const { result } = renderHook(() =>
    useWorkspaceStore({ initialWorktrees: [worktree, featureWorktree], services }),
  );

  await act(async () => {
    await result.current.openTab(worktree);
  });
  const tabId = result.current.state.layout.activeTabId!;
  const [firstLeafId] = tabPanes(result.current.state, tabId).leafIds;

  // The split pane runs in a different worktree, because one worktree holds one writer lease.
  await act(async () => {
    await result.current.openTab(featureWorktree);
    result.current.activateTab(tabId);
    await result.current.splitPane("horizontal", { tabId, targetLeafId: firstLeafId });
  });

  const { layout, leafIds } = tabPanes(result.current.state, tabId);
  expect(result.current.state.layout.tabs).toHaveLength(2);
  expect(layout.root).toMatchObject({ type: "split", direction: "horizontal" });
  expect(leafIds).toHaveLength(2);
  expect(leafIds[0]).toBe(firstLeafId);
  expect(layout.activeLeafId).toBe(leafIds[1]);
  expect(layout.sessionIdsByLeafId[leafIds[0]]).not.toBe(layout.sessionIdsByLeafId[leafIds[1]]);
});

it("closes one pane, keeps the tab, and releases only the closed pane's PTY", async () => {
  const { services } = createServices();
  const { result } = renderHook(() =>
    useWorkspaceStore({ initialWorktrees: [worktree, featureWorktree], services }),
  );

  await act(async () => {
    await result.current.openTab(worktree);
  });
  const tabId = result.current.state.layout.activeTabId!;
  const [firstLeafId] = tabPanes(result.current.state, tabId).leafIds;

  await act(async () => {
    await result.current.openTab(featureWorktree);
    result.current.activateTab(tabId);
    await result.current.splitPane("vertical", { tabId, targetLeafId: firstLeafId });
  });

  const { layout, leafIds } = tabPanes(result.current.state, tabId);
  const closingLeafId = leafIds[1];
  const closingSessionId = layout.sessionIdsByLeafId[closingLeafId];
  const closingBackendId = result.current.state.sessions[closingSessionId].backendSessionId!;
  const survivingSessionId = layout.sessionIdsByLeafId[firstLeafId];

  await act(async () => {
    await result.current.closePane(tabId, closingLeafId);
  });

  const after = tabPanes(result.current.state, tabId);
  expect(result.current.state.layout.tabs).toHaveLength(2);
  expect(after.layout.root).toEqual({ type: "leaf", leafId: firstLeafId });
  expect(after.layout.activeLeafId).toBe(firstLeafId);
  expect(services.closeTerminal).toHaveBeenCalledWith(closingBackendId);
  expect(result.current.state.sessions[closingSessionId]).toBeUndefined();
  expect(result.current.state.sessions[survivingSessionId]).toBeDefined();
});

it("resizes and reorders panes without disturbing their backend sessions", async () => {
  const { services } = createServices();
  const { result } = renderHook(() =>
    useWorkspaceStore({ initialWorktrees: [worktree, featureWorktree], services }),
  );

  await act(async () => {
    await result.current.openTab(worktree);
  });
  const tabId = result.current.state.layout.activeTabId!;
  const [firstLeafId] = tabPanes(result.current.state, tabId).leafIds;

  await act(async () => {
    await result.current.openTab(featureWorktree);
    result.current.activateTab(tabId);
    await result.current.splitPane("horizontal", { tabId, targetLeafId: firstLeafId });
  });

  const before = tabPanes(result.current.state, tabId);
  const backendsBefore = Object.values(result.current.state.sessions).map((session) => session.backendSessionId);

  act(() => {
    result.current.setPaneRatio(tabId, "", 0.75);
    result.current.swapPanes(tabId, before.leafIds[0], before.leafIds[1]);
  });

  const after = tabPanes(result.current.state, tabId);
  expect(after.layout.root).toMatchObject({ type: "split", ratio: 0.75 });
  expect(after.leafIds).toEqual([before.leafIds[1], before.leafIds[0]]);
  expect(after.layout.sessionIdsByLeafId).toEqual(before.layout.sessionIdsByLeafId);
  expect(Object.values(result.current.state.sessions).map((session) => session.backendSessionId)).toEqual(
    backendsBefore,
  );
  expect(services.closeTerminal).not.toHaveBeenCalled();
  expect(services.spawnTerminal).toHaveBeenCalledTimes(2);
});

it("closes the tab when its last remaining pane closes", async () => {
  const { services } = createServices();
  const { result } = renderHook(() =>
    useWorkspaceStore({ initialWorktrees: [worktree, featureWorktree], services }),
  );

  await act(async () => {
    await result.current.openTab(worktree);
    await result.current.openTab(featureWorktree);
  });
  const tabId = result.current.state.layout.activeTabId!;
  const { leafIds, layout } = tabPanes(result.current.state, tabId);
  const closingBackendId = result.current.state.sessions[layout.sessionIdsByLeafId[leafIds[0]]].backendSessionId!;

  await act(async () => {
    await result.current.closePane(tabId, leafIds[0]);
  });

  expect(result.current.state.layout.tabs).toHaveLength(1);
  expect(result.current.state.layout.layoutsByTabId[tabId]).toBeUndefined();
  expect(services.closeTerminal).toHaveBeenCalledWith(closingBackendId);
});

